package com.apexstreet.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="automation_light_overrides", indexes=@Index(name="ix_override_area_status",columnList="area_id,status"))
public class AutomationLightOverride { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="area_id",nullable=false) private Area area; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="street_light_id",nullable=false) private StreetLight streetLight; @Enumerated(EnumType.STRING) @Column(nullable=false,length=15) private AutomationOverrideMode mode; @Column(nullable=false) private Integer brightness; @Column(name="duration_minutes") private Integer durationMinutes; @Column(name="expires_at") private LocalDateTime expiresAt; @Enumerated(EnumType.STRING) @Column(nullable=false,length=15) private AutomationOverrideStatus status=AutomationOverrideStatus.ACTIVE; @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt; @PrePersist void c(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;} @PreUpdate void u(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public Area getArea(){return area;} public void setArea(Area v){area=v;} public StreetLight getStreetLight(){return streetLight;} public void setStreetLight(StreetLight v){streetLight=v;} public AutomationOverrideMode getMode(){return mode;} public void setMode(AutomationOverrideMode v){mode=v;} public Integer getBrightness(){return brightness;} public void setBrightness(Integer v){brightness=v;} public Integer getDurationMinutes(){return durationMinutes;} public void setDurationMinutes(Integer v){durationMinutes=v;} public LocalDateTime getExpiresAt(){return expiresAt;} public void setExpiresAt(LocalDateTime v){expiresAt=v;} public AutomationOverrideStatus getStatus(){return status;} public void setStatus(AutomationOverrideStatus v){status=v;} }
